      firstName: "Đức",
      middleName: "Vũ Minh",
      lastName: "Nguyễn",
      birthDate: "25/11/2005",
      birthDateIso: "2005-11-25",
      birthDay: "25",
      birthMonth: "11",
      birthYear: "2005",
      studentId: "0174268",
      className: "68QD1",
